import{_ as e}from"./chunks/files.B17OUyrr.js";import{_ as o,c as i,o as r,a2 as s}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"Conozca qDiff","description":"Una breve introducción a la comparación de archivos, carpetas y proyectos con qDiff en su Mac.","frontmatter":{"title":"Conozca qDiff","description":"Una breve introducción a la comparación de archivos, carpetas y proyectos con qDiff en su Mac."},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md","lastUpdated":1794296122000}'),n={name:"es/guide/introduction.md"};function t(c,a,l,d,u,p){return r(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="conozca-qdiff" tabindex="-1">Conozca qDiff <a class="header-anchor" href="#conozca-qdiff" aria-label="Permalink to &quot;Conozca qDiff&quot;">​</a></h1><p>qDiff responde a una sola pregunta: <strong>¿qué cambió?</strong> Coloque dos versiones una junto a otra y todo lo diferente aparece marcado en color, para que deje de comparar línea por línea con la vista.</p><img src="'+e+'" alt="Dos archivos comparados uno al lado del otro" class="guide-shot"><h2 id="tres-usos-habituales" tabindex="-1">Tres usos habituales <a class="header-anchor" href="#tres-usos-habituales" aria-label="Permalink to &quot;Tres usos habituales&quot;">​</a></h2><ul><li><strong>Dos archivos</strong> — un borrador y su revisión, una configuración antes y después, dos exportaciones de la misma herramienta. Las palabras cambiadas se resaltan dentro de la línea.</li><li><strong>Dos carpetas</strong> — una carpeta de trabajo y su copia de seguridad. Los archivos nuevos, modificados y ausentes se distinguen a simple vista, y puede volver a sincronizar ambos lados.</li><li><strong>Una carpeta de proyecto</strong> — todo lo que ha tocado, reunido en una sola lista. Lea cada cambio y confirme sin cambiar de ventana.</li></ul><p>También puede comparar imágenes, archivos comprimidos y archivos que no son de texto plano. <a href="./more.html">Vea más formas de comparar</a>.</p><h2 id="empiece-en-tres-pasos" tabindex="-1">Empiece en tres pasos <a class="header-anchor" href="#empiece-en-tres-pasos" aria-label="Permalink to &quot;Empiece en tres pasos&quot;">​</a></h2><ol><li>Abra qDiff y arrastre dos archivos o carpetas a la ventana, o elíjalos desde el menú Archivo.</li><li>Mire las líneas coloreadas. Haga clic en el pequeño mapa del lateral o use los botones anterior / siguiente para recorrer cada cambio.</li><li>Edite, copie o sincronice lo que haya que corregir. Guarde una imagen de la comparación si alguien más debe verla.</li></ol><div class="tip custom-block"><p class="custom-block-title">Sin configuración previa</p><p>No hay que crear ninguna cuenta ni configurar nada antes de la primera comparación. Todo funciona sin conexión.</p></div><h2 id="gratuito-y-privado" tabindex="-1">Gratuito y privado <a class="header-anchor" href="#gratuito-y-privado" aria-label="Permalink to &quot;Gratuito y privado&quot;">​</a></h2><p>Todas las comparaciones están disponibles de forma gratuita. La versión gratuita solo muestra una pequeña marca en la barra de pestañas; una compra única la elimina. qDiff lee únicamente los archivos que usted elige y no envía nada a ningún sitio: consulte la <a href="./../privacy/">Política de Privacidad</a> para más detalles.</p><h2 id="¿necesita-ayuda" tabindex="-1">¿Necesita ayuda? <a class="header-anchor" href="#¿necesita-ayuda" aria-label="Permalink to &quot;¿Necesita ayuda?&quot;">​</a></h2><p>Las <a href="./faq.html">preguntas frecuentes</a> responden a las dudas más habituales. Si algo sigue sin ir bien, <a href="./../guide/support.html">escríbanos</a> y le ayudaremos.</p>',13)])])}const g=o(n,[["render",t]]);export{f as __pageData,g as default};
